import{_ as d,o as e,c as r,a2 as a}from"./chunks/framework.Bg-Zxr5O.js";const p=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[],"relativePath":"manual-en/Testing-for-normality.md","filePath":"manual-en/Testing-for-normality.md","lastUpdated":1785684581000}'),n={name:"manual-en/Testing-for-normality.md"};function o(i,t,s,l,h,m){return e(),r("div",null,[...t[0]||(t[0]=[a(`<h4 id="_5-2-5-testing-for-normality" tabindex="-1">5.2.5 Testing for normality <a class="header-anchor" href="#_5-2-5-testing-for-normality" aria-label="Permalink to &quot;5.2.5 Testing for normality&quot;">​</a></h4><p>Many statistical tests rely upon certain properties of the data. One common property, upon which many linear tests depend, is that of normality — the data must have been drawn from a normal distribution. It is necessary then to ensure normality before deciding upon the test procedure to use. One way to do this uses the <code>EXAMINE</code> command.</p><p>In the following example, a researcher was examining the failure rates of equipment produced by an engineering company. The file repairs.sav contains the mean time between failures (<strong>mtbf</strong>) of some items of equipment subject to the study. Before performing linear analysis on the data, the researcher wanted to ascertain that the data is normally distributed.</p><pre><code>PSPP&gt; get file=&#39;/usr/local/share/pspp/examples/repairs.sav&#39;.
PSPP&gt; examine mtbf
                /statistics=descriptives.
</code></pre><p>This produces the following output:</p><table tabindex="0"><thead><tr><th></th><th></th><th></th><th>Statistic</th><th>Std. Error</th></tr></thead><tbody><tr><td>Mean time between failures (months)</td><td>Mean</td><td>8.78</td><td>1.10</td><td></td></tr><tr><td>95% Confidence Interval for Mean</td><td>Lower Bound</td><td>6.53</td><td></td><td></td></tr><tr><td>Upper Bound</td><td>11.04</td><td></td><td></td><td></td></tr><tr><td>5% Trimmed Mean</td><td>8.20</td><td></td><td></td><td></td></tr><tr><td>Median</td><td>8.29</td><td></td><td></td><td></td></tr><tr><td>Variance</td><td>36.34</td><td></td><td></td><td></td></tr><tr><td>Std. Deviation</td><td>6.03</td><td></td><td></td><td></td></tr><tr><td>Minimum</td><td>1.63</td><td></td><td></td><td></td></tr><tr><td>Maximum</td><td>26.47</td><td></td><td></td><td></td></tr><tr><td>Range</td><td>24.84</td><td></td><td></td><td></td></tr><tr><td>Interquartile Range</td><td>6.03</td><td></td><td></td><td></td></tr><tr><td>Skewness</td><td>1.65</td><td>.43</td><td></td><td></td></tr><tr><td>Kurtosis</td><td>3.41</td><td>.83</td><td></td><td></td></tr></tbody></table><p>A normal distribution has a skewness and kurtosis of zero. The skewness of <strong>mtbf</strong> in the output above makes it clear that the mtbf figures have a lot of positive skew and are therefore not drawn from a normally distributed variable. Positive skew can often be compensated for by applying a logarithmic transformation, as in the following continuation of the example:</p><pre><code>PSPP&gt; compute mtbf_ln = ln (mtbf).
PSPP&gt; examine mtbf_ln
                /statistics=descriptives.
</code></pre><p>which produces the following additional output:</p><table tabindex="0"><thead><tr><th></th><th></th><th></th><th>Statistic</th><th>Std. Error</th></tr></thead><tbody><tr><td>mtbf_ln</td><td>Mean</td><td>1.95</td><td>.13</td><td></td></tr><tr><td>95% Confidence Interval for Mean</td><td>Lower Bound</td><td>1.69</td><td></td><td></td></tr><tr><td>Upper Bound</td><td>2.22</td><td></td><td></td><td></td></tr><tr><td>5% Trimmed Mean</td><td>1.96</td><td></td><td></td><td></td></tr><tr><td>Median</td><td>2.11</td><td></td><td></td><td></td></tr><tr><td>Variance</td><td>.49</td><td></td><td></td><td></td></tr><tr><td>Std. Deviation</td><td>.70</td><td></td><td></td><td></td></tr><tr><td>Minimum</td><td>.49</td><td></td><td></td><td></td></tr><tr><td>Maximum</td><td>3.28</td><td></td><td></td><td></td></tr><tr><td>Range</td><td>2.79</td><td></td><td></td><td></td></tr><tr><td>Interquartile Range</td><td>.88</td><td></td><td></td><td></td></tr><tr><td>Skewness</td><td>-.37</td><td>.43</td><td></td><td></td></tr><tr><td>Kurtosis</td><td>.01</td><td>.83</td><td></td><td></td></tr></tbody></table><p>The <code>COMPUTE</code> command in the first line above performs the logarithmic transformation:</p><pre><code>compute mtbf_ln = ln (mtbf).
</code></pre><p>Rather than redefining the existing variable, this use of <code>COMPUTE</code> defines a new variable <strong>mtbf_ln</strong> which is the natural logarithm of <strong>mtbf</strong>. The final command in this example calls <code>EXAMINE</code> on this new variable. The results show that both the skewness and kurtosis for <strong>mtbf_ln</strong> are very close to zero. This provides some confidence that the <strong>mtbf_ln</strong> variable is normally distributed and thus safe for linear analysis. In the event that no suitable transformation can be found, then it would be worth considering an appropriate non-parametric test instead of a linear one. See <a href="./NPAR-TESTS">NPAR TESTS</a>, for information about non-parametric tests.</p>`,13)])])}const c=d(n,[["render",o]]);export{p as __pageData,c as default};
